seen={r['path']:set() for r in rows}
for item in load('_read_ledger.json'):
    row=next(r for r in rows if r['path']==item['path']); assert item['sha256']==row['sha256']
    a,b=item['displayed_lines'];seen[item['path']].update(range(a,b+1))
for item in load('_bounded_read_ledger.json'):
    row=next(r for r in rows if r['path']==item['path']); assert item['sha256']==row['sha256']
    seen[item['path']].update(item['displayed_line_numbers'])
def spans(numbers):
    out=[]
    for n in sorted(numbers):
        if out and n==out[-1][1]+1:out[-1][1]=n
        else:out.append([n,n])
    return out
reviews=[]; line_counts={}
for i,r in enumerate(rows):
    b=(R/r['path']).read_bytes(); assert h(b)==r['sha256']; ls=b.decode('utf8').splitlines();n=len(ls);line_counts[i]=n
    assert seen[r['path']]<=set(range(1,n+1))
    full=seen[r['path']]==set(range(1,n+1)); assert full==(i not in (104,144))
    reviewed=spans(seen[r['path']]);assessment=notes[str(i)]
    review={'path':r['path'],'sha256':r['sha256'],'bytes':len(b),'source_line_count':n,'full_source_read':full,'reviewed_lines':reviewed,'reviewed_line_count':len(seen[r['path']]),'review_level':'full_raw_body_substantive_review' if full else 'partial_raw_body_plus_bounded_whole_population_checks','reading_method':'Complete numbered raw source displays with file-specific assessment; linked owners and automated parsing do not receive new body-reading credit.' if full else 'Exact raw display ranges plus explicitly separate population checks; no template transfer or complete-body claim.','assessment':assessment,'actual_execution_status':'Declarations and historical retained evidence reviewed; no retained program, provider or native execution. Independent controls are listed separately.','source_evidence':[{'path':r['path'],'sha256':r['sha256'],'lines':[a,z],'range_kind':'raw body read'} for a,z in reviewed]}
    if not full:
        review['unread_lines']=spans(set(range(1,n+1))-seen[r['path']])
        review['bounded_artifact_review']={'covered_lines':[1,n],'coverage_kind':'whole JSON parse and explicitly enumerated predicates, not complete semantic reading','checks_artifact':'dag/reviews/additional_eis_artifacts_remaining_catalog_checks.json' if i==104 else 'dag/reviews/additional_eis_artifacts_remaining_controls.json','limits':'Catalog-only prose/regex/evidence semantics not all adjudicated.' if i==104 else 'Three large warning-output strings hashed and accounted for, not fully read; full retained receipt is itself not all historical unabridged logs.'}
    reviews.append(review)
def ev(i,a=1,b=None,kind='source body read'):
    return {'path':rows[i]['path'],'sha256':rows[i]['sha256'],'lines':[a,b if b is not None else line_counts[i]],'range_kind':kind,'full_source_read':reviews[i]['full_source_read']}
def item(ident,claim,ids,ceiling,next_action,controls=(),status='source_review'):
    return {'id':ident,'claim':claim,'source_evidence':ids,'evidence_kind':status,'controls':list(controls),'ceiling':ceiling,'next_action':next_action}

claims=[
item('EA-C01','These declarations contribute reusable control proposals: typed refusal versus checker outage, task/source-bound replay, an explicit canonical JSON profile, dual benign/hostile fixtures, scoped second-signal admission and protected vocabulary. They do not create a new workflow mechanism for each task-domain answer.',[ev(5),ev(58),ev(63,12,29),ev(65),ev(98),ev(99),ev(103)],'Most files are declarative candidates, references or historical fixtures. Enforcement and general detector adequacy belong to separately reviewed owners; no new workflow family or empirical gain is claimed.','Consolidate around the existing screening/admission/custody owners with a task-specific encoding and independently checked semantic predicate. Never feed retained mathematical answers into a new benchmark as truth.'),
item('EA-C02','The three v2 truth-boundary specs define precise finite conjunctions over supplied fields. An independent interpreter reproduces all six stored fixture hits/nonhits.',[ev(133),ev(135),ev(137),ev(139)],'Six fixture outcomes are not unrestricted truth detection, authenticated identity independence, authorization or proof of runtime enforcement; the specs say runtime_enforcement=false and status=PROPOSED.','Keep the finite subject schema, semantic scope map and host admission requirements explicit when reusing these predicates.',['EA-T06'],'full body plus fresh finite interpreter'),
item('EA-C03','Historical custody/repair receipts preserve original failures, mutant/restoration sequences and explicit open obligations. Their scoped pass statuses are compatible with full-programme-open/blocked outcomes and single-worker review.',[ev(141),ev(142,768,781),ev(143),ev(144,745,759),ev(145)],'Current work checks retained data and a finite subset of internal contracts. No historical command, signer, native build, model call or independent review was reproduced; stored output custody still has unresolved bindings.','Retain failed/global/platform results with successful bounded tests, and require original-byte custody plus the admitted owner before replaying any claim.',['EA-T09','EA-T10'],'full semantic source-body review plus historical accounting; no historical re-execution')
]
findings=[
item('EA-F01','The 54 root JSON files carrying both fixture strings and a target_pattern do not form 54 validated paired regex regressions: default Python re gives 10 bad-only hits, 41 neither hits and 3 hits on both; IGNORECASE|DOTALL gives 11,40,3. The clean-architecture pattern requires a literal where-layer clause absent from its Python fixture.',[ev(14,4,11),ev(23),ev(24),ev(25)],'This is a declared direct-regex/fixture contract check, not a production false-negative rate. Some target strings name diagnostic classes and may require an adapter; that adapter is not established by these strings. Prior EPR06 already covers generated both-trigger templates.','Specify the intended detector input and adapter, then require matched bad/good controls under that exact route before admission.',['EA-T01'],'fresh bounded regex checks plus full bodies'),
item('EA-F02','Several repaired mathematical fixtures assert conclusions not implied by their displayed invariant: alternating cochains need not have positive circulation; d squared zero does not force a positive spectral floor; a five-point-per-coordinate sample grid does not certify an unrestricted polynomial identity without degree or ideal evidence.',[ev(1,9,11),ev(17,9,11),ev(34,9,11),ev(59),ev(67),ev(80)],'Exact finite controls refute these inference steps in isolation. They do not refute an original pilot calculation under extra assumptions, nor a separately supplied algebraic certificate that is absent here.','Require actual cochain/matrix/polynomial inputs, relevant carrier assumptions and a replayable certificate; retain prose only as diagnostic examples.',['EA-T02','EA-T03','EA-T04'],'full bodies plus exact finite counterexamples'),
item('EA-F03','The premature-fiber-exclusion negative fixture is not necessarily erroneous: if the base 618-equation variety is genuinely empty, adding 48 constraints cannot make it nonempty. Counting 666 constraints also does not establish a positive separation gap.',[ev(42,9,11),ev(81)],'The set-intersection implication is exact; this review neither establishes nor denies historical base emptiness. The missing condition is whether that premise was certified.','Distinguish unverified base emptiness from verified empty base, and preserve the original obligation when constructing counterexamples.',['EA-T05'],'full bodies plus finite intersection control'),
item('EA-F04','Some repaired fixtures weaken or incompletely check the obligation: the axiom example proves True instead of discharging the removed false proposition; non-None gates are unconditionally labeled CHECKLIST_CERTIFIED; a mapping check still leaves op unchecked; a scoped type-ignore still suppresses the erroneous assignment; FiniteDifferenceBound only stores arbitrary values and hedged=True.',[ev(89,20,32),ev(68,12,16),ev(68,31,39),ev(88,27,31),ev(62,20,30),ev(77,28,41)],'These are source-level fixture limitations, not fresh defects asserted in the actual production owners. No Lean kernel, typechecker or fixture execution occurred.','Test task preservation and the original postcondition, independently of lexical repair. Use fixtures to show exactly the boundary they implement, not full certification.'),
item('EA-F05','The v2 predicates have explicit semantic boundaries: bounded-mode scope mismatch is outside the unrestricted-only rule, same producer/verifier identity is outside the self-certification rule when claim_mode differs, and proposal MERGE is refused irrespective of approval_reference. Identity strings and scope labels do not establish causal independence or logical entailment.',[ev(133),ev(135),ev(137),ev(139)],'These are scoped behaviors, not demonstrated host bypasses. They may be intentional policy; runtime_enforcement is false and a host may impose additional gates.','Document the conjunctions and their exclusions; supply independently admitted scope/identity/approval semantics before claiming broader truth or authority enforcement.',['EA-T06'],'full bodies plus finite interpreter boundary cases'),
item('EA-F06','Adjacent declarations disagree on PERSONA_AUTHORITY_LEAK: failure_classes marks is_native=false while native_pharmacy includes PersonaAuthorityLeak in native_class_codes.',[ev(100,71,75),ev(101,11,23)],'Metadata inconsistency only; this does not override actual native/host owners or establish a runtime error.','Choose a canonical role-partition declaration and test generated mappings against it.',['EA-T08'],'full bodies plus cross-declaration check'),
item('EA-F07','Two reviewed evidence_sha256 values have 36 and 24 hex characters, respectively. Both historical validation-to-QA digest links also fail current raw/LF/CRLF byte profiles. Thus these declarations are not self-sufficient current-byte custody evidence.',[ev(20,6,8),ev(28,6,8),ev(141),ev(142,164,164),ev(143),ev(144,758,758)],'Digest shape and current-byte comparison do not authenticate evidence. Original artifact bytes/canonicalization are not established; mismatch is not proof of fabrication or a failed original execution. Prior EPR13 separately records 21/33 output mismatches and is not reissued here.','Preserve historical data; identify the exact digest contract and original artifacts before treating these references as verified custody.',['EA-T07','EA-T09'],'full semantic bodies plus byte/shape checks'),
item('EA-F08','The ten closeout mutations all record nonzero mutant and zero restored exits, but the missing-host mutant tail is AttributeError. Its detected=true therefore does not alone show semantic enforcement of typed missing-host refusal. Several native tails also omit the actual failing assertion.',[ev(145,40,58),ev(145,139,198)],'The stored failures may be useful regression evidence; nonzero exit cannot by itself distinguish a meaningful mutant kill from malformed mutation/setup failure. No retained test was rerun.','Preserve the negative result and capture the exact failed assertion, baseline and restored/mutated source binding before using a mutation score as adequacy evidence.',['EA-T10'],'full receipt body plus fresh historical count check')
]

