report={'schema_version':1,'review_id':'additional_eis_artifacts_remaining','status':'checkpoint_full_body_review_continues','scope_manifest':'dag/reviews/additional_eis_artifacts_remaining_scope.json','scope_sha256':scope_sha,'source_commit':scope['source_commit'],'summary':summary,'method':['All 144 concise source/declaration/retained-receipt raw bodies displayed in full and assessed individually, including all embedded instructions as inert corpus data.','Catalog and boundary validation retain exact partial ranges and bounded automated predicates. Parsed coverage does not become full reading. No exact-template transfer is claimed at this checkpoint.','Historical source/path/command references remain provenance, not new execution or dependency body-reading credit. Prior report claims are explicitly reconciled.','No source edits/deletions, retained programs/native builds/providers/network calls/private benchmark or credential access. Only own prefixed helpers/reports are written.'],'claims':claims,'findings':findings,'prior_evidence_reconciliation':reconciliation,'file_reviews':reviews,'execution_evidence':{'path':'dag/reviews/additional_eis_artifacts_remaining_controls.json','sha256':h(Path(str(P)+'_controls.json').read_bytes()),'helper':'dag/reviews/additional_eis_artifacts_remaining_controls.py','helper_sha256':h(Path(str(P)+'_controls.py').read_bytes()),'controls':[x['id'] for x in controls['controls']],'fresh_scope':'Standalone bounded regex/AST/arithmetic/JSON/YAML accounting; no production evaluator execution.','historical_scope':'Historical test commands, elapsed times, outcomes and review identities are stored assertions only.'},'artifact_evidence':{'catalog_checks':'dag/reviews/additional_eis_artifacts_remaining_catalog_checks.json','catalog_checks_sha256':h(Path(str(P)+'_catalog_checks.json').read_bytes()),'root_catalog_comparisons':comparison_counts,'catalog_full_semantic_read':False,'boundary_unread_raw_lines':[221,240,478]},'limitations':['Catalog-only declarations and three long native warning-output strings are not fully human-read. All 146 have a disposition, but two full-body reviews remain explicitly open and will continue.','No external literature, physical theorem, historical answer or claimed model-performance figure was independently validated. No sealed benchmark material was accessed.','No root/spec/catalog synchronization edit, source repair, admission action or history deletion was performed.','Source snapshots outside this 146-file scope and owners referenced by prior reports retain their separate attribution.','Current raw/LF/CRLF mismatches cannot reconstruct historical transformations. Existing support/pilot migration archives are not presumed to supply original EIS receipts.']}
Path(str(P)+'.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n',encoding='utf8')

md=['# EIS remaining declarations and retained evidence','',f"Checkpoint: {summary['disposed']}/146 files have dispositions; **144 full raw-body reads; 2 partial with bounded whole-population checks**. The two full-body reviews remain open and continue after this checkpoint. The frozen scope contains {summary['bytes']:,} bytes and {summary['lines']:,} lines. Full bodies account for {summary['full_body_lines']:,} lines; another {summary['additional_partial_lines']:,} raw lines were read in the partial artifacts.",'','No originals were edited and no retained command, native build, provider or private benchmark was accessed. Eleven fresh standalone controls are separate from the historical test records.','',f"Scope SHA-256: `{scope_sha}`.",'','## Contribution and limits','']
